{"results": [{"id": "FAM:SF-PAP-096", "label": "Study family SF-PAP-096: Play-type classifier assisted-flag leak (SPOT_UP 100% makes)", "score": 0.932, "reached_via": ["request matches the question or hypothesis of FAM:SF-PAP-096 (0.82)"], "attributes": {"observed_research_question": "Play-type classifier assisted-flag leak (SPOT_UP 100% makes)", "auto_outcome_status": "artifact", "observed_hypothesis": "Possession-level play types from PBP contain unbiased predictive structure.", "observed_result": "SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "assisted flag on makes only produced SPOT_UP 2.83 PPP", "observed_sample_and_power": "NOT_RECORDED", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Sequence-level PPP by inferred play type before rewriting play_type_inferrer.py.", "observed_verdict": "artifact_found", "observed_failure_type": "C_artifact", "observed_notes": "Engineering discovery that poisoned simulation. May overlap APP slices."}, "relationships": []}, {"id": "FAM:SF-CHT-025", "label": "Study family SF-CHT-025: Play-type labeling audit: OTHER/DRIVE foul leakage", "score": 0.926, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-025 (0.81)"], "attributes": {"observed_research_question": "Play-type labeling audit: OTHER/DRIVE foul leakage", "auto_outcome_status": "artifact", "observed_hypothesis": "Play-type PPP differences are real efficiency, not labeling/foul artifacts.", "observed_result": "OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "OTHER PPP inflated by 36% foul endings; DRIVE 12pp below foul benchmark; initiation_type maps 0.7%.", "observed_sample_and_power": "50,668 possessions in the initiation_type check", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Per-PT diagnostic of foul-ending share vs PPP; initiation_type mapping.", "observed_verdict": "artifact_found"}, "relationships": []}, {"id": "FAM:SF-APPM-014", "label": "Study family SF-APPM-014: Play-type label accuracy / distribution audit", "score": 0.926, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-014 (0.81)"], "attributes": {"observed_research_question": "Play-type label accuracy / distribution audit", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Inferred play-type labels match benchmark volumes, foul rates, PPP and known team identities.", "observed_result": "Audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "'play type labels have systematic issues that undermine adaptation findings'; foul possessions leak into OTHER.", "observed_verdict": "tool_eval_fail"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:leakage"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:LEAKAGE_LOOKAHEAD"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-059", "label": "Study family SF-APPS-059: Sequence-memory horizon test (per-lag vs aggregated window)", "score": 0.817, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-059 (0.82)"], "attributes": {"observed_research_question": "Sequence-memory horizon test (per-lag vs aggregated window)", "auto_outcome_status": "supported", "observed_hypothesis": "Increasing prior-possession history changes the opponent's next-possession outcome after controlling for game state.", "observed_result": "Per-lag GBT AUC N=0 0.5621 -> N=1 0.5863 (d+0.0242) -> N=3 0.5907 -> N=8 0.5911. R2 0.0051 -> 0.0133. Aggregated window declines after N=1 (AUC 0.5868 -> 0.5687 at N=8). Effective horizon ~2-3 possessions.", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Short-memory horizon is stable OOS; almost all gain is lag-1, plateau by lag 4. Absolute AUC still only ~0.591.", "observed_sample_and_power": "n=1,024,980 possessions; time-split test 2025-26", "observed_verdict": "supported", "observed_failure_type": "D_positive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-070"}]}, {"id": "FAM:SF-CHT-086", "label": "Study family SF-CHT-086: LLM / ex-ante usefulness of suppression context (leakage audit)", "score": 0.621, "reached_via": ["request matches RQC:RQC-109 (0.80); FAM:SF-CHT-086 auto_addresses_question RQC:RQC-109"], "attributes": {"observed_research_question": "LLM / ex-ante usefulness of suppression context (leakage audit)", "auto_outcome_status": "artifact", "observed_hypothesis": "An LLM layer can reason about suppression context beyond the engine, or predicting suppression from H1 is a viable label.", "observed_result": "Label is mostly an RTM artifact. Apparent LLM skill was leakage; what survives is small/noisy; engine misses are selection/override not missing graph facts. Margin of LLM vs engine described as literally zero after leaka [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Suppression label selected on the outcome; remaining LLM edge not statistically retrievable."}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:RTM_SELECTION"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-005"}]}, {"id": "FAM:SF-APPA-005", "label": "Study family SF-APPA-005: Defensive scheme change within game and across games (inferred labels)", "score": 0.586, "reached_via": ["request matches RQC:RQC-040 (0.75); FAM:SF-APPA-005 auto_addresses_question RQC:RQC-040", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.75); FAM:SF-APPA-005 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Defensive scheme change within game and across games (inferred labels)", "auto_outcome_status": "untestable", "observed_hypothesis": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily.", "observed_result": "Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Doc caveat: inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise.", "observed_sample_and_power": "523 cells; 440 pairs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}, {"id": "FAM:SF27", "label": "Study family SF27: Linear team+opponent+play_type baseline vs simulation kernel", "score": 0.522, "reached_via": ["FAM:SF-PAP-096 auto_related_family (record_link_related_to) FAM:SF27", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.75); FAM:SF27 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Linear team+opponent+play_type baseline vs simulation kernel", "auto_outcome_status": "inconclusive", "observed_hypothesis": "The Monte Carlo simulation kernel predicts margins better than a linear PPP~team+opponent+play_type model.", "observed_result": ["[CHT-004] SPOT_UP PPP 2.83 to 1.16 (fixed); linear margin R = +0.505; kernel Det. R = +0.466 (gap 0.001 vs linear additive R = +0.467); 5/5 perturbation tests.", "[PAP-097] linear Margin R=+0.505, win accuracy 64-68%; deterministic kernel R=+0.466 vs linear +0.467 (gap 0.001) after the multiplicative rewrite; earlier additive kernel compressed variance"], "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": ["[CHT-004] NOT_RECORDED", "[PAP-097] kernel R=+0.466 matches linear +0.467; does not beat the simple model"], "observed_sample_and_power": "[CHT-004] NOT_RECORDED"}, "relationships": []}, {"id": "FAM:SF-APPS-068", "label": "Study family SF-APPS-068: Possession Control Index incremental R2 over ORtg (PCI is DRtg proxy)", "score": 0.521, "reached_via": ["FAM:SF-APPS-059 auto_related_family (record_link_related_to) FAM:SF-APPS-068", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.75); FAM:SF-APPS-068 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Possession Control Index incremental R2 over ORtg (PCI is DRtg proxy)", "auto_outcome_status": "artifact", "observed_hypothesis": "PCI (halfcourt PPP + second-chance - TO - transition leakage) explains Net Rating beyond ORtg, Pace, and FGA/poss.", "observed_result": "A R2=0.763 OOS 0.761; C R2=0.902 OOS 0.919; dR2=+0.139. Offensive-control components add +0.005 R2 beyond ORtg. Net~ORtg+leakage R2=0.948. corr(leakage, DRtg)=+0.894. PCI univariate r=+0.863 vs ORtg +0.866.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Headline PCI gain is leakage tracking DRtg (+0.89); offensive-control dR2=+0.005. Baseline omitted defense by construction (Net=ORtg-DRtg).", "observed_sample_and_power": "n=120 team-seasons; OOS 2025-26 30 teams"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:leakage"}, {"rel": "auto_has_risk", "node": "RISK:LEAKAGE_LOOKAHEAD"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPS-070", "label": "Study family SF-APPS-070: H1 usage as predictor of H2 suppression (distribution shift)", "score": 0.521, "reached_via": ["FAM:SF-APPS-059 auto_related_family (record_link_related_to) FAM:SF-APPS-070", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.75); FAM:SF-APPS-070 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "H1 usage as predictor of H2 suppression (distribution shift)", "auto_outcome_status": "rejected", "observed_hypothesis": "First-half reliance on a play type predicts second-half suppression after controlling for H1 PPP / mean reversion.", "observed_result": "Test B: all BH-adjusted null/WEAK (PNR ATT=+0.0313 BH_p=0.0658 WEAK; others NULL). Test C top-1 acc=0.550 vs mean-reversion baseline 0.511 (+0.039) vs most-used 0.239. Test A PULL_UP slope -0.0581 p=0.0030; CUT -0.0917 p [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Matched ATT does not survive BH; predictive lift over mean reversion is only +0.039 (0.550 vs 0.511). Bulk of H2 suppression is RTM.", "observed_sample_and_power": "n=8873 team-games; Test C test n=1008"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:RTM_SELECTION"}]}, {"id": "FAM:SF-APPS-073", "label": "Study family SF-APPS-073: Persistent Impact Score lag curves (global then within-team)", "score": 0.521, "reached_via": ["FAM:SF-APPS-059 auto_related_family (record_link_related_to) FAM:SF-APPS-073", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.75); FAM:SF-APPS-073 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Persistent Impact Score lag curves (global then within-team)", "auto_outcome_status": "artifact", "observed_hypothesis": "Running play type X raises the same team's next 1-5 possession PPP vs a matched baseline (action memory).", "observed_result": "Global horizons: DRIVE/SPOT_UP/TRANSITION=5; others 0 (PNR/CUT/POST_UP/PUTBACK). SPOT_UP lag-1 lift +0.027 ctrl_p=0.0000. Within-team: all horizons 0 except SPOT_UP horizon(all)=1; PNR lag-1 within_team_lift=-0.0218.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Flat non-decaying global lifts disappear after team-season demeaning; remaining within-team memory is essentially none except SPOT_UP lag-1.", "observed_sample_and_power": "DRIVE lag-1 n=163696; SPOT_UP n=175021", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-059"}]}], "n_results": 10}

